    StringBuilder__push_str(&sb, "        arena.buf[start + n] = 0 as u8;\n");
    StringBuilder__push_str(&sb, "        arena.off = start + n + 1 as u32;\n");
    StringBuilder__push_str(&sb, "        let p: *u8 = ptr_offset(arena.buf, start);\n");
    StringBuilder__push_str(&sb, "        return p as *const c_char as str;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "struct Arena { buf: own *u8, cap: u32, off: u32, alloc: Allocator }\n");
    StringBuilder__push_str(&sb, "impl Arena {\n");
    StringBuilder__push_str(&sb, "    pub fn with_capacity(a: Allocator, bytes: u32) -> Arena {\n");
    StringBuilder__push_str(&sb, "        let buf: own *u8 = a.alloc_fn(a.state, bytes) as own *u8;\n");
    StringBuilder__push_str(&sb, "        return Arena { buf: buf, cap: bytes, off: 0 as u32, alloc: a };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn alloc_borrowed<T>(*self) -> *T {\n");
    StringBuilder__push_str(&sb, "        let aligned: u32 = (self.off + 7 as u32) & ~(7 as u32);\n");
    StringBuilder__push_str(&sb, "        let need: u32 = size_of(T) as u32;\n");
    StringBuilder__push_str(&sb, "        if aligned + need > self.cap { return null; }\n");
    StringBuilder__push_str(&sb, "        let p: *u8 = ptr_offset(self.buf, aligned);\n");
    StringBuilder__push_str(&sb, "        self.off = aligned + need;\n");
    StringBuilder__push_str(&sb, "        return p as *T;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "struct StringBuilder { buf: own *u8, len: u32, cap: u32, alloc: Allocator }\n");
    StringBuilder__push_str(&sb, "impl StringBuilder {\n");
    StringBuilder__push_str(&sb, "    pub fn with_capacity(a: Allocator, hint: u32) -> StringBuilder {\n");
    StringBuilder__push_str(&sb, "        let cap: u32 = if hint < 16 as u32 { 16 as u32 } else { hint };\n");
    StringBuilder__push_str(&sb, "        let buf: own *u8 = a.alloc_fn(a.state, cap) as own *u8;\n");
    StringBuilder__push_str(&sb, "        return StringBuilder { buf: buf, len: 0 as u32, cap: cap, alloc: a };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    fn grow(*self, new_cap: u32) {\n");
    StringBuilder__push_str(&sb, "        let new_buf: own *u8 = self.alloc.alloc_fn(self.alloc.state, new_cap) as own *u8;\n");
    StringBuilder__push_str(&sb, "        let src: Slice<u8> = Slice { ptr: self.buf as *const u8, len: self.len };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = 0 as u32;\n");
    StringBuilder__push_str(&sb, "        while i < self.len { new_buf[i] = src[i]; i = i + 1 as u32; }\n");
    StringBuilder__push_str(&sb, "        self.alloc.free_fn(self.alloc.state, self.buf as *c_void, self.cap);\n");
    StringBuilder__push_str(&sb, "        self.buf = new_buf;\n");
    StringBuilder__push_str(&sb, "        self.cap = new_cap;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn push_byte(*self, b: u8) {\n");
    StringBuilder__push_str(&sb, "        if self.len + 1 as u32 > self.cap { self.grow(self.cap * 2 as u32); }\n");
    StringBuilder__push_str(&sb, "        self.buf[self.len] = b;\n");
    StringBuilder__push_str(&sb, "        self.len = self.len + 1 as u32;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn push_str(*self, s: str) {\n");
    StringBuilder__push_str(&sb, "        let n: u32 = cstr_len(s);\n");
    StringBuilder__push_str(&sb, "        let need: u32 = self.len + n;\n");
    StringBuilder__push_str(&sb, "        if need > self.cap {\n");
    StringBuilder__push_str(&sb, "            let mut new_cap: u32 = self.cap;\n");
    StringBuilder__push_str(&sb, "            while new_cap < need { new_cap = new_cap * 2 as u32; }\n");
    StringBuilder__push_str(&sb, "            self.grow(new_cap);\n");
    StringBuilder__push_str(&sb, "        }\n");
    StringBuilder__push_str(&sb, "        let src: Slice<u8> = Slice { ptr: s as *const u8, len: n };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = 0 as u32;\n");
    StringBuilder__push_str(&sb, "        while i < n { self.buf[self.len + i] = src[i]; i = i + 1 as u32; }\n");
    StringBuilder__push_str(&sb, "        self.len = self.len + n;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn push_int(*self, n: int) {\n");
    StringBuilder__push_str(&sb, "        if n == 0 { self.push_byte(48 as u8); return; }\n");
    StringBuilder__push_str(&sb, "        let mut u: u32 = 0 as u32;\n");
    StringBuilder__push_str(&sb, "        if n < 0 { self.push_byte(45 as u8); u = 0 as u32 - n as u32; } else { u = n as u32; }\n");
    StringBuilder__push_str(&sb, "        let mut digits: [u8; 10] = [0 as u8; 10];\n");
    StringBuilder__push_str(&sb, "        let mut idx: u32 = 0 as u32;\n");
    StringBuilder__push_str(&sb, "        while u > 0 as u32 {\n");
    StringBuilder__push_str(&sb, "            digits[idx] = (48 as u32 + u % 10 as u32) as u8;\n");
    StringBuilder__push_str(&sb, "            u = u / 10 as u32;\n");
    StringBuilder__push_str(&sb, "            idx = idx + 1 as u32;\n");
    StringBuilder__push_str(&sb, "        }\n");
    StringBuilder__push_str(&sb, "        while idx > 0 as u32 { idx = idx - 1 as u32; self.push_byte(digits[idx]); }\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn length(*const self) -> u32 { return self.len; }\n");
    StringBuilder__push_str(&sb, "    pub fn as_slice(*const self) -> Slice<u8> {\n");
    StringBuilder__push_str(&sb, "        return Slice { ptr: self.buf as *const u8, len: self.len };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "struct String { ptr: own *u8, len: u32, alloc: Allocator }\n");
    StringBuilder__push_str(&sb, "impl String {\n");
    StringBuilder__push_str(&sb, "    pub fn with_str(a: Allocator, s: str) -> String {\n");
