    StringBuilder__push_str(&sb, "        let src: Slice<u8> = Slice { ptr: s as *const u8, len: n };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = 0 as u32;\n");
    StringBuilder__push_str(&sb, "        while i < n { buf[i] = src[i]; i = i + 1 as u32; }\n");
    StringBuilder__push_str(&sb, "        buf[n] = 0 as u8;\n");
    StringBuilder__push_str(&sb, "        return String { ptr: buf, len: n, alloc: a };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn empty(a: Allocator) -> String {\n");
