    StringBuilder__push_str(&sb, "        buf[0 as u32] = 0 as u8;\n");
    StringBuilder__push_str(&sb, "        return String { ptr: buf, len: 0 as u32, alloc: a };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn build(sb: StringBuilder) -> String {\n");
    StringBuilder__push_str(&sb, "        sb.buf[sb.len] = 0 as u8;\n");
    StringBuilder__push_str(&sb, "        return String { ptr: sb.buf as own *u8, len: sb.len, alloc: sb.alloc };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn length(*const self) -> u32 { return self.len; }\n");
    StringBuilder__push_str(&sb, "    pub fn as_slice(*const self) -> Slice<u8> {\n");
    StringBuilder__push_str(&sb, "        return Slice { ptr: self.ptr as *const u8, len: self.len };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn as_str(*const self) -> str { return self.ptr as str; }\n");
    StringBuilder__push_str(&sb, "    pub fn free(self) {\n");
    StringBuilder__push_str(&sb, "        self.alloc.free_fn(self.alloc.state, self.ptr as *c_void, self.len + 1 as u32);\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "impl Eq for String {\n");
    StringBuilder__push_str(&sb, "    pub fn eq(*const self, other: *const String) -> bool {\n");
    StringBuilder__push_str(&sb, "        return str::eq(self.as_str(), other.as_str());\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "impl Hash for String {\n");
    StringBuilder__push_str(&sb, "    pub fn hash(*const self) -> u32 { return str::hash(self.as_str()); }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "impl Clone for String {\n");
    StringBuilder__push_str(&sb, "    pub fn clone(*const self) -> String {\n");
    StringBuilder__push_str(&sb, "        return String::with_str(self.alloc, self.as_str());\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "struct Vec<T> { ptr: own *T, count: u32, cap: u32, alloc: Allocator }\n");
    StringBuilder__push_str(&sb, "struct VecIter<T> { data: *const T, len: u32, pos: u32 }\n");
    StringBuilder__push_str(&sb, "impl Vec<T> {\n");
    StringBuilder__push_str(&sb, "    pub fn with_capacity(a: Allocator, hint: u32) -> Vec<T> {\n");
    StringBuilder__push_str(&sb, "        let cap: u32 = if hint < 8 as u32 { 8 as u32 } else { hint };\n");
    StringBuilder__push_str(&sb, "        let bytes: u32 = size_of(T) as u32 * cap;\n");
    StringBuilder__push_str(&sb, "        let p: own *T = a.alloc_fn(a.state, bytes) as own *T;\n");
    StringBuilder__push_str(&sb, "        return Vec { ptr: p, count: 0 as u32, cap: cap, alloc: a };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn length(*const self) -> u32 { return self.count; }\n");
    StringBuilder__push_str(&sb, "    fn grow(*self, new_cap: u32) {\n");
    StringBuilder__push_str(&sb, "        let bytes: u32 = size_of(T) as u32 * new_cap;\n");
    StringBuilder__push_str(&sb, "        let new_ptr: own *T = self.alloc.alloc_fn(self.alloc.state, bytes) as own *T;\n");
    StringBuilder__push_str(&sb, "        let src: Slice<T> = Slice { ptr: self.ptr as *const T, len: self.count };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = 0 as u32;\n");
    StringBuilder__push_str(&sb, "        while i < self.count { new_ptr[i] = src[i] as T; i = i + 1 as u32; }\n");
    StringBuilder__push_str(&sb, "        let old_bytes: u32 = size_of(T) as u32 * self.cap;\n");
    StringBuilder__push_str(&sb, "        self.alloc.free_fn(self.alloc.state, self.ptr as *c_void, old_bytes);\n");
    StringBuilder__push_str(&sb, "        self.ptr = new_ptr;\n");
    StringBuilder__push_str(&sb, "        self.cap = new_cap;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn push(*self, x: T) {\n");
    StringBuilder__push_str(&sb, "        if self.count + 1 as u32 > self.cap { self.grow(self.cap * 2 as u32); }\n");
    StringBuilder__push_str(&sb, "        self.ptr[self.count] = x;\n");
    StringBuilder__push_str(&sb, "        self.count = self.count + 1 as u32;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn get(*const self, i: u32) -> Option<T> {\n");
    StringBuilder__push_str(&sb, "        if i >= self.count { return Option::None; }\n");
    StringBuilder__push_str(&sb, "        let s: Slice<T> = Slice { ptr: self.ptr as *const T, len: self.count };\n");
    StringBuilder__push_str(&sb, "        return Option::Some(s[i]);\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn as_slice(*const self) -> Slice<T> {\n");
    StringBuilder__push_str(&sb, "        return Slice { ptr: self.ptr as *const T, len: self.count };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn iter(*const self) -> VecIter<T> {\n");
    StringBuilder__push_str(&sb, "        return VecIter { data: self.ptr as *const T, len: self.count, pos: 0 as u32 };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "impl Slice<T> {\n");
    StringBuilder__push_str(&sb, "    pub fn length(*const self) -> u32 { return self.len; }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "impl Iterator for VecIter<T> {\n");
    StringBuilder__push_str(&sb, "    pub fn next(*self) -> Option<T> {\n");
    StringBuilder__push_str(&sb, "        if self.pos >= self.len { return Option::None; }\n");
    StringBuilder__push_str(&sb, "        let s: Slice<T> = Slice { ptr: self.data, len: self.len };\n");
    StringBuilder__push_str(&sb, "        let v: T = s[self.pos];\n");
    StringBuilder__push_str(&sb, "        self.pos = self.pos + 1 as u32;\n");
    StringBuilder__push_str(&sb, "        return Option::Some(v);\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "}\n");
    StringBuilder__push_str(&sb, "struct Slot<K, V> { state: u8, hash: u32, key: K, value: V }\n");
    StringBuilder__push_str(&sb, "struct HashMap<K, V> { slots: own *Slot<K, V>, count: u32, cap: u32, alloc: Allocator }\n");
    StringBuilder__push_str(&sb, "struct HashMapIter<K, V> { data: *const Slot<K, V>, len: u32, pos: u32 }\n");
    StringBuilder__push_str(&sb, "impl HashMap<K, V> {\n");
    StringBuilder__push_str(&sb, "    pub fn with_capacity(a: Allocator, hint: u32) -> HashMap<K, V> {\n");
    StringBuilder__push_str(&sb, "        let raw: u32 = if hint < 8 as u32 { 8 as u32 } else { hint };\n");
    StringBuilder__push_str(&sb, "        let mut cap: u32 = 1 as u32;\n");
    StringBuilder__push_str(&sb, "        while cap < raw { cap = cap << 1 as u32; }\n");
    StringBuilder__push_str(&sb, "        let bytes: u32 = size_of(Slot<K, V>) as u32 * cap;\n");
    StringBuilder__push_str(&sb, "        let p: own *Slot<K, V> = a.alloc_fn(a.state, bytes) as own *Slot<K, V>;\n");
    StringBuilder__push_str(&sb, "        mem_zero(p, bytes);\n");
    StringBuilder__push_str(&sb, "        return HashMap { slots: p, count: 0 as u32, cap: cap, alloc: a };\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn length(*const self) -> u32 { return self.count; }\n");
    StringBuilder__push_str(&sb, "    fn grow(*self, new_cap: u32) {\n");
    StringBuilder__push_str(&sb, "        let bytes: u32 = size_of(Slot<K, V>) as u32 * new_cap;\n");
    StringBuilder__push_str(&sb, "        let new_p: own *Slot<K, V> = self.alloc.alloc_fn(self.alloc.state, bytes) as own *Slot<K, V>;\n");
    StringBuilder__push_str(&sb, "        mem_zero(new_p, bytes);\n");
    StringBuilder__push_str(&sb, "        let old_cap: u32 = self.cap;\n");
    StringBuilder__push_str(&sb, "        let old_view: Slice<Slot<K, V>> = Slice { ptr: self.slots as *const Slot<K, V>, len: self.cap };\n");
    StringBuilder__push_str(&sb, "        let mut j: u32 = 0 as u32;\n");
    StringBuilder__push_str(&sb, "        while j < old_cap {\n");
    StringBuilder__push_str(&sb, "            let s: Slot<K, V> = old_view[j];\n");
    StringBuilder__push_str(&sb, "            if s.state == 1 as u8 {\n");
    StringBuilder__push_str(&sb, "                let new_view: Slice<Slot<K, V>> = Slice { ptr: new_p as *const Slot<K, V>, len: new_cap };\n");
    StringBuilder__push_str(&sb, "                let mut i: u32 = s.hash & (new_cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "                while true {\n");
    StringBuilder__push_str(&sb, "                    let n: Slot<K, V> = new_view[i];\n");
    StringBuilder__push_str(&sb, "                    if n.state != 1 as u8 {\n");
    StringBuilder__push_str(&sb, "                        new_p[i] = Slot { state: 1 as u8, hash: s.hash, key: s.key, value: s.value };\n");
    StringBuilder__push_str(&sb, "                        break;\n");
    StringBuilder__push_str(&sb, "                    }\n");
    StringBuilder__push_str(&sb, "                    i = (i + 1 as u32) & (new_cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "                }\n");
    StringBuilder__push_str(&sb, "            }\n");
    StringBuilder__push_str(&sb, "            j = j + 1 as u32;\n");
    StringBuilder__push_str(&sb, "        }\n");
    StringBuilder__push_str(&sb, "        let old_bytes: u32 = size_of(Slot<K, V>) as u32 * old_cap;\n");
    StringBuilder__push_str(&sb, "        self.alloc.free_fn(self.alloc.state, self.slots as *c_void, old_bytes);\n");
    StringBuilder__push_str(&sb, "        self.slots = new_p;\n");
    StringBuilder__push_str(&sb, "        self.cap = new_cap;\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn contains(*const self, k: K) -> bool {\n");
    StringBuilder__push_str(&sb, "        let h: u32 = k.hash();\n");
    StringBuilder__push_str(&sb, "        let sview: Slice<Slot<K, V>> = Slice { ptr: self.slots as *const Slot<K, V>, len: self.cap };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = h & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        while true {\n");
    StringBuilder__push_str(&sb, "            let s: Slot<K, V> = sview[i];\n");
    StringBuilder__push_str(&sb, "            if s.state == 0 as u8 { return false; }\n");
    StringBuilder__push_str(&sb, "            if s.state == 1 as u8 && s.hash == h {\n");
    StringBuilder__push_str(&sb, "                if k.eq(s.key) { return true; }\n");
    StringBuilder__push_str(&sb, "            }\n");
    StringBuilder__push_str(&sb, "            i = (i + 1 as u32) & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        }\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn get(*const self, k: K) -> Option<V> {\n");
    StringBuilder__push_str(&sb, "        let h: u32 = k.hash();\n");
    StringBuilder__push_str(&sb, "        let sview: Slice<Slot<K, V>> = Slice { ptr: self.slots as *const Slot<K, V>, len: self.cap };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = h & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        while true {\n");
    StringBuilder__push_str(&sb, "            let s: Slot<K, V> = sview[i];\n");
    StringBuilder__push_str(&sb, "            if s.state == 0 as u8 { return Option::None; }\n");
    StringBuilder__push_str(&sb, "            if s.state == 1 as u8 && s.hash == h {\n");
    StringBuilder__push_str(&sb, "                if k.eq(s.key) { return Option::Some(s.value); }\n");
    StringBuilder__push_str(&sb, "            }\n");
    StringBuilder__push_str(&sb, "            i = (i + 1 as u32) & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        }\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn insert(*self, k: K, v: V) {\n");
    StringBuilder__push_str(&sb, "        if (self.count + 1 as u32) * 4 as u32 > self.cap * 3 as u32 { self.grow(self.cap * 2 as u32); }\n");
    StringBuilder__push_str(&sb, "        let h: u32 = k.hash();\n");
    StringBuilder__push_str(&sb, "        let sview: Slice<Slot<K, V>> = Slice { ptr: self.slots as *const Slot<K, V>, len: self.cap };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = h & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        while true {\n");
    StringBuilder__push_str(&sb, "            let s: Slot<K, V> = sview[i];\n");
    StringBuilder__push_str(&sb, "            if s.state != 1 as u8 {\n");
    StringBuilder__push_str(&sb, "                self.slots[i] = Slot { state: 1 as u8, hash: h, key: k, value: v };\n");
    StringBuilder__push_str(&sb, "                self.count = self.count + 1 as u32;\n");
    StringBuilder__push_str(&sb, "                return;\n");
    StringBuilder__push_str(&sb, "            }\n");
    StringBuilder__push_str(&sb, "            if s.hash == h && k.eq(s.key) {\n");
    StringBuilder__push_str(&sb, "                self.slots[i] = Slot { state: 1 as u8, hash: h, key: k, value: v };\n");
    StringBuilder__push_str(&sb, "                return;\n");
    StringBuilder__push_str(&sb, "            }\n");
    StringBuilder__push_str(&sb, "            i = (i + 1 as u32) & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        }\n");
    StringBuilder__push_str(&sb, "    }\n");
    StringBuilder__push_str(&sb, "    pub fn remove(*self, k: K) {\n");
    StringBuilder__push_str(&sb, "        let h: u32 = k.hash();\n");
    StringBuilder__push_str(&sb, "        let sview: Slice<Slot<K, V>> = Slice { ptr: self.slots as *const Slot<K, V>, len: self.cap };\n");
    StringBuilder__push_str(&sb, "        let mut i: u32 = h & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        while true {\n");
    StringBuilder__push_str(&sb, "            let s: Slot<K, V> = sview[i];\n");
    StringBuilder__push_str(&sb, "            if s.state == 0 as u8 { return; }\n");
    StringBuilder__push_str(&sb, "            if s.state == 1 as u8 && s.hash == h {\n");
    StringBuilder__push_str(&sb, "                if k.eq(s.key) {\n");
    StringBuilder__push_str(&sb, "                    self.slots[i] = Slot { state: 2 as u8, hash: s.hash, key: s.key, value: s.value };\n");
    StringBuilder__push_str(&sb, "                    self.count = self.count - 1 as u32;\n");
    StringBuilder__push_str(&sb, "                    return;\n");
    StringBuilder__push_str(&sb, "                }\n");
    StringBuilder__push_str(&sb, "            }\n");
    StringBuilder__push_str(&sb, "            i = (i + 1 as u32) & (self.cap - 1 as u32);\n");
    StringBuilder__push_str(&sb, "        }\n");
